dir:





















































&DefaultButton;




function dir$options(p){
  this.constructor(p);
}
dir$options.prototype = new DirEvent();
dir$options.prototype.afterInit = function(){
  var p = this._dir, g = p.options.parent;
  switch(p.valForm("type")) {
    case "C":
        p.setHidden("val_text", false);
        p.setHidden("val_num,  val_cbo , val_date", true);

        p.valForm("val_text", p.valForm("val"));
        break;
    case "N":
        p.setHidden("val_num", false);
        p.setHidden("val_text,   val_cbo,  val_date", true);
        console.log(parseInt(p.valForm("inputmask")));
        p.jObject("val_num").number({digit: parseInt(p.valForm("inputmask"))});
        p.valForm("val_num", p.valForm("val"));
        break;
    case "O":
        p.setHidden("val_cbo", false);
        p.setHidden("val_text, val_num, val_date", true);

        var xLan = ($.lan == 'v' ? 0 : 1);
        var arMask = p.valForm("inputmask").split("><")[xLan].split("#");

        var sHtml = "";
        for(var i = 0; i < arMask.length; i+=2)
          sHtml += "<" + "option value='" + arMask[i] + "'" + (p.valForm("val") == arMask[i] ? " selected" : "") + ">" + arMask[i + 1] + "<" + "/option>";
        p.jObject("val_cbo").html(sHtml);
        break;
    case "D":
        p.setHidden("val_text, val_num, val_cbo", true);
        p.setHidden("val_date", false);

        p.valForm("val_date", p.valForm("val"));
        break;
  }
}

dir$options.prototype.beforeButtonDialogClick = function(id){
  var p = this._dir, g = p.options.parent;
  if(id == "ok"){
    switch(p.valForm("type")) {
      case "C":
          p.valForm("val", p.valForm("val_text"));
          p.valForm("val_mask", p.valForm("val_text"));
          break;
      case "N":
          p.valForm("val", p.valForm("val_num"));
          p.valForm("val_mask", p.valForm("val_num"));
          break;
      case "O":
          p.valForm("val", p.valForm("val_cbo"));
          p.valForm("val_mask", p.jObject("val_cbo").find('option:selected').text());
          break;
      case "D":
          p.valForm("val", $.date(p.valForm("val_date")));
          p.valForm("val_mask", p.jObject("val_date").val());
          break;
    }
  }
  return true;
}








